using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.TKT.DocumentosTicket;using GraphApi.Services.TKT.DocumentosTicket;namespace GraphApi.Controllers.TKT.DocumentosTicket{    /// <summary>    /// Gestión de DocumentosTickets: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("TKT/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre DocumentosTickets")]    public class DocumentosTicketController : Controller    {        private readonly IDocumentosTicketService _objService;        public DocumentosTicketController(IDocumentosTicketService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los DocumentosTickets, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="documentoTicketID">DocumentoTicketID</param>        /// <param name="ticketID">TicketID</param>        /// <param name="documentoID">DocumentoID</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de DocumentosTickets</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar DocumentosTickets",            Description = "Devuelve DocumentosTickets aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadDocumentosTicket>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadDocumentosTicket>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? documentoTicketID,            [FromQuery] int? ticketID,            [FromQuery] int? documentoID,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetDocumentosTicketsDynamic(                documentoTicketID,                 ticketID,                 documentoID,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo DocumentosTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del DocumentosTicket a crear.</param>        /// <returns>El DocumentosTicket recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear DocumentosTickets",            Description = "Inserta un nuevo DocumentosTicket en la base de datos."        )]        [ProducesResponseType(typeof(clReadDocumentosTicket), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadDocumentosTicket>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateDocumentosTicket objInput)        {            var vCreated = await _objService.CreateDocumentosTicket(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de DocumentosTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del DocumentosTicket.</param>        /// <returns>El DocumentosTicket actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar DocumentosTickets",            Description = "Actualiza uno o varios campos de DocumentosTicket existente."        )]        [ProducesResponseType(typeof(clReadDocumentosTicket), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadDocumentosTicket>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateDocumentosTicket objInput)        {            var vUpdated = await _objService.UpdateDocumentosTicket(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un DocumentosTicket por su ID.        /// </summary>        [HttpDelete("{nDocumentosTicketID:int}")]        [SwaggerOperation(            Summary = "Eliminar DocumentosTicket",            Description = "Borra un DocumentosTicket si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nDocumentosTicketID)        {            var success = await _objService.DeleteDocumentosTicket(nDocumentosTicketID);            return success ? NoContent() : NotFound();        }    }}